-- KHUNYUI DATABASE 004 — REALTIME + MENU IMAGE STORAGE\n\n-- Public menu image bucket: customer pages need to display edited food photos without authentication.\ninsert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values\n('menu-images','menu-images',true,10485760,array['image/jpeg','image/png','image/webp'])\non conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;\n\ndo $$ begin create policy menu_images_owner_insert on storage.objects for insert to authenticated with check(bucket_id='menu-images' and exists(select 1 from public.store_members sm where sm.user_id=(select auth.uid()) and sm.store_id::text=(storage.foldername(name))[1])); exception when duplicate_object then null; end $$;\ndo $$ begin create policy menu_images_owner_update on storage.objects for update to authenticated using(bucket_id='menu-images' and exists(select 1 from public.store_members sm where sm.user_id=(select auth.uid()) and sm.store_id::text=(storage.foldername(name))[1])) with check(bucket_id='menu-images' and exists(select 1 from public.store_members sm where sm.user_id=(select auth.uid()) and sm.store_id::text=(storage.foldername(name))[1])); exception when duplicate_object then null; end $$;\ndo $$ begin create policy menu_images_owner_delete on storage.objects for delete to authenticated using(bucket_id='menu-images' and exists(select 1 from public.store_members sm where sm.user_id=(select auth.uid()) and sm.store_id::text=(storage.foldername(name))[1])); exception when duplicate_object then null; end $$;\n\n-- Postgres Changes for the owner's current orders listener.\ndo $$ begin alter publication supabase_realtime add table public.orders; exception when duplicate_object then null; end $$;\n\n-- Broadcast changes for existing owner private channels.\ncreate or replace function public.khunyui_broadcast_change() returns trigger\nlanguage plpgsql security definer set search_path='' as $$\ndeclare sid uuid; topic text;\nbegin\n  if TG_TABLE_NAME='stores' then sid=coalesce(NEW.id,OLD.id);\n  else sid=coalesce(NEW.store_id,OLD.store_id); end if;\n  if TG_TABLE_NAME='orders' then topic='store-orders:'||sid::text;\n  elsif TG_TABLE_NAME='menu_items' then topic='store-menu:'||sid::text;\n  else topic='store-settings:'||sid::text; end if;\n  perform realtime.broadcast_changes(topic,TG_OP,TG_OP,TG_TABLE_NAME,TG_TABLE_SCHEMA,NEW,OLD);\n  return coalesce(NEW,OLD);\nend $$;\n\ndo $$ begin create trigger orders_broadcast after insert or update or delete on public.orders for each row execute function public.khunyui_broadcast_change(); exception when duplicate_object then null; end $$;\ndo $$ begin create trigger menu_broadcast after insert or update or delete on public.menu_items for each row execute function public.khunyui_broadcast_change(); exception when duplicate_object then null; end $$;\ndo $$ begin create trigger store_broadcast after update on public.stores for each row execute function public.khunyui_broadcast_change(); exception when duplicate_object then null; end $$;\ndo $$ begin create trigger access_broadcast after insert or update or delete on public.customer_access for each row execute function public.khunyui_broadcast_change(); exception when duplicate_object then null; end $$;\n\n-- Only members of the matching store can join the private owner channels.\ndo $$ begin\n create policy khunyui_owner_receive_broadcast on realtime.messages for select to authenticated using(\n   realtime.messages.extension='broadcast' and exists(\n     select 1 from public.store_members sm where sm.user_id=(select auth.uid()) and (select realtime.topic()) in ('store-orders:'||sm.store_id::text,'store-menu:'||sm.store_id::text,'store-settings:'||sm.store_id::text)\n   )\n );\nexception when duplicate_object then null; end $$;\n